package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Elements;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.nodes.Document.createEl;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class Element_siblingElements_TriageGen2Test {

    private static final Element PARENT_ELT = createEl("div");
    private static final Element CHILD_ELT = createEl("span");
    private static final Element CHILD_ELT2 = createEl("span");

    @Test
    public void siblingElements_NullParent() {
        // Arrange
        Element nullParent = null;

        // Act
        Elements elements = nullParent.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(0, elements.size());
    }

    @Test
    public void siblingElements_EmptyParent() {
        // Arrange
        Element emptyParent = createEl();

        // Act
        Elements elements = emptyParent.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(0, elements.size());
    }

    @Test
    public void siblingElements_SingleChild() {
        // Arrange
        PARENT_ELT.appendChild(CHILD_ELT);

        // Act
        Elements elements = PARENT_ELT.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(1, elements.size());
        assertSame(CHILD_ELT, elements.first());
    }

    @Test
    public void siblingElements_MultipleChildren() {
        // Arrange
        PARENT_ELT.appendChild(CHILD_ELT);
        PARENT_ELT.appendChild(CHILD_ELT2);

        // Act
        Elements elements = PARENT_ELT.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(2, elements.size());
        assertSame(CHILD_ELT, elements.first());
        assertSame(CHILD_ELT2, elements.last());
    }

    @Test
    public void siblingElements_NullChild() {
        // Arrange
        PARENT_ELT.appendChild(null);

        // Act
        Elements elements = PARENT_ELT.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(1, elements.size());
        assertNull(elements.first());
    }

    @Test
    public void siblingElements_ChildWithChildren() {
        // Arrange
        CHILD_ELT.appendChild(createEl("p"));

        // Act
        Elements elements = PARENT_ELT.siblingElements();

        // Assert
        assertNotNull(elements);
        assertEquals(1, elements.size());
        assertSame(CHILD_ELT, elements.first());
    }
}
